.checkbox-control__label a:hover,
.checkbox-control__label a:focus-visible {
  text-decoration: underline;
}

.checkbox-control__label a:focus-visible {
  outline: 2px solid var(--color-primary);
  outline-offset: 2px;
  border-radius: 2px;
